local ServiceDescriptorResolver = require(script.Parent.ServiceDescriptorResolver)
local ServiceResolver = require(script.Parent.ServiceResolver)
local LuaTypeProvider = require(script.Parent.LuaTypeProvider)
local ServiceCollection = require(script.Parent.ServiceCollection)
local EnumerableHelper = require(script.Parent.EnumerableHelper)

local ServiceResolverManager = {}
ServiceResolverManager.__index = ServiceResolverManager

function ServiceResolverManager.new(services: ServiceCollection.Type, luaTypeProvider: ILuaTypeProvider)
	local self = setmetatable({}, ServiceResolverManager)
	self._services = services
	self._resolvers = {}
	self._luaTypeProvider = luaTypeProvider

	return self
end

function ServiceResolverManager:_lastOrDefaultService(type: string)
	if not self._services._descriptors then
		return nil
	end

	-- 倒序遍历 self._services
	for i = #self._services._descriptors, 1, -1 do
		local descriptor = self._services._descriptors[i]
		if descriptor.ServiceType == type then
			return descriptor
		end
	end
end

function ServiceResolverManager:Resolve(serviceProvider, service, descriptorOrUnsolved, unsolved)
	local descriptor = descriptorOrUnsolved

	if unsolved then
		return ServiceDescriptorResolver.Resolve(serviceProvider, service, descriptor, unsolved, self._luaTypeProvider)
	end
	local resolver = self:_getOrAddServiceResolver(service)
	if not resolver then
		return nil
	end
	local result = resolver:Relove(serviceProvider, service, descriptorOrUnsolved)
	return result
end

function ServiceResolverManager:_getOrAddServiceResolver(service)
	if not self._resolvers[service] then
		local resolver = self:_newResolver(service)
		if not resolver then
			return nil
		end
		self._resolvers[service] = resolver
	end
	return self._resolvers[service]
end

function ServiceResolverManager:_newResolver(serviceType)
	if serviceType.IsGenericTypeDefinition then
		error("type Is GenericTypeDefinition")
	end

	local match = self:_lastOrDefaultService(serviceType)

	if not match and serviceType.IsGenericType then
		-- local genericDefine = serviceType:GetGenericTypeDefinition()
		-- match = self:_lastOrDefaultService(genericDefine)
	end

	if match then
		return ServiceResolver.new(match, self._luaTypeProvider)
	else
		local isEnumerable, genericType = EnumerableHelper.Parse(serviceType)
		if isEnumerable then
			local matches = {}
			for i = #self._services._descriptors, 1, -1 do
				local descriptor = self._services._descriptors[i]
				if descriptor.ServiceType == genericType then
					table.insert(matches, descriptor)
				end
			end
			return ServiceResolver.newWithDescriptors(serviceType, genericType, matches, self._luaTypeProvider)
		end
	end

	return nil
end

function ServiceResolverManager:Dispose()
	for k in pairs(self._resolvers) do
		self._resolvers[k] = nil
	end
end

return ServiceResolverManager
